package factory_flow.Factory_Flow

import org.sireum._
import art._
import factory_flow._

// Do not edit this file as it will be overwritten if HAMR codegen is rerun

@sig trait ProtectedWorkPriorityResolver_Api {
  def id: Art.BridgeId
  def admission_Id : Art.PortId
  def protectionContext_Id : Art.PortId
  def intentFact_Id : Art.PortId

  // Logika spec var representing port state for outgoing data port
  @spec var intentFact: Factory_Flow.FlowIntentFact = $

  def put_intentFact(value : Factory_Flow.FlowIntentFact) : Unit = {
    Contract(
      Modifies(intentFact),
      Ensures(
        intentFact == value
      )
    )
    Spec {
      intentFact = value
    }

    Art.putValue(intentFact_Id, Factory_Flow.FlowIntentFact_Payload(value))
  }

  def logInfo(msg: String): Unit = {
    Art.logInfo(id, msg)
  }

  def logDebug(msg: String): Unit = {
    Art.logDebug(id, msg)
  }

  def logError(msg: String): Unit = {
    Art.logError(id, msg)
  }
}

@datatype class ProtectedWorkPriorityResolver_Initialization_Api (
  val id: Art.BridgeId,
  val admission_Id : Art.PortId,
  val protectionContext_Id : Art.PortId,
  val intentFact_Id : Art.PortId) extends ProtectedWorkPriorityResolver_Api

@datatype class ProtectedWorkPriorityResolver_Operational_Api (
  val id: Art.BridgeId,
  val admission_Id : Art.PortId,
  val protectionContext_Id : Art.PortId,
  val intentFact_Id : Art.PortId) extends ProtectedWorkPriorityResolver_Api {

  // Logika spec var representing port state for incoming data port
  @spec var admission: Factory_Flow.AdmissionFact = $

  def get_admission() : Option[Factory_Flow.AdmissionFact] = {
    Contract(
      Ensures(
        Res == Some(admission)
      )
    )
    val value : Option[Factory_Flow.AdmissionFact] = Art.getValue(admission_Id) match {
      case Some(Factory_Flow.AdmissionFact_Payload(v)) => Some(v)
      case Some(v) =>
        Art.logError(id, s"Unexpected payload on port admission.  Expecting 'Factory_Flow.AdmissionFact_Payload' but received ${v}")
        None[Factory_Flow.AdmissionFact]()
      case _ => None[Factory_Flow.AdmissionFact]()
    }
    return value
  }

  // Logika spec var representing port state for incoming data port
  @spec var protectionContext: Factory_Flow.ProtectionContext = $

  def get_protectionContext() : Option[Factory_Flow.ProtectionContext] = {
    Contract(
      Ensures(
        Res == Some(protectionContext)
      )
    )
    val value : Option[Factory_Flow.ProtectionContext] = Art.getValue(protectionContext_Id) match {
      case Some(Factory_Flow.ProtectionContext_Payload(v)) => Some(v)
      case Some(v) =>
        Art.logError(id, s"Unexpected payload on port protectionContext.  Expecting 'Factory_Flow.ProtectionContext_Payload' but received ${v}")
        None[Factory_Flow.ProtectionContext]()
      case _ => None[Factory_Flow.ProtectionContext]()
    }
    return value
  }
}
